(()=>{const s=document.getElementById('mondialScreen'),flow=document.getElementById('mondialFlow'),lang=document.documentElement.lang.startsWith('en')?'en':'pt';const t={pt:{login:'Login',home:'Casa conectada',alert:'Alerta de incêndio',assist:'Assistência',track:'Socorro a caminho',enter:'Entrar no Mondial Home',monitor:'Monitorar casa',risk:'Risco de incêndio',riskText:'Foi detectada uma temperatura elevada em sua residência.',help:'Solicitar assistência',eta:'Socorro a caminho · 09:59'},en:{login:'Login',home:'Connected home',alert:'Fire alert',assist:'Assistance',track:'Emergency help on the way',enter:'Enter Mondial Home',monitor:'Monitor home',risk:'Fire risk',riskText:'A high temperature was detected in your home.',help:'Request assistance',eta:'Emergency help on the way · 09:59'}}[lang];const states=['login','home','alert','assist','track'];function render(k){flow.querySelectorAll('button').forEach(b=>b.setAttribute('aria-current',b.dataset.s===k));if(k==='login')s.innerHTML='<div class="mondial-bg"></div><div class="mondial-shade"></div><div class="mondial-ui"><img class="mondial-logo" src="/assets/images/design/prototypes/icon.jpg" alt=""><div class="mondial-word">Mondial Home</div><div class="mondial-actions"><button class="primary" data-next="home">'+t.enter+'</button></div></div>';if(k==='home')s.innerHTML='<div class="mondial-bg"></div><div class="mondial-shade"></div><div class="mondial-ui"><strong>MONDIAL HOME</strong><div class="mondial-status">27ºC · 33% · '+(lang==='en'?'GOOD':'BOM')+'</div><div class="mondial-actions"><button class="ghost" data-next="alert">'+t.monitor+'</button></div></div>';if(k==='alert')s.innerHTML='<div class="mondial-bg"></div><div class="mondial-shade"></div><div class="mondial-ui"><div class="mondial-alert"><strong>'+t.risk+'</strong>'+t.riskText+'<div class="mondial-actions" style="margin-top:18px"><button class="primary" data-next="assist">'+t.help+'</button></div></div></div>';if(k==='assist')s.innerHTML='<div class="mondial-bg"></div><div class="mondial-shade"></div><div class="mondial-ui"><div class="mondial-alert"><img class="mondial-agent" src="/assets/images/design/prototypes/agent.jpg" alt=""><strong>Mondial Assistance</strong><div class="mondial-actions"><button class="primary" data-next="track">'+t.help+'</button></div></div></div>';if(k==='track')s.innerHTML='<div class="mondial-map"></div><div class="mondial-ui"><strong>MONDIAL ASSISTANCE</strong><div class="mondial-status">'+t.eta+'</div></div>';s.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>render(b.dataset.next))}states.forEach(k=>{const b=document.createElement('button');b.dataset.s=k;b.textContent=t[k];b.onclick=()=>render(k);flow.appendChild(b)});render('login')})();